record.field:
reference = custom_values.get("_pending_waypoint_reference")

if not reference:
    result = {
        "exit_code": -1,
        "message": "No waypoint reference in flight plan context."
    }
else:
    waypoint = tower_waypoints.get_by_reference(reference)

    if not waypoint:
        result = {
            "exit_code": -2,
            "message": "Waypoint not found."
        }
    else:
        if waypoint.state == "error":
            result = {
                "exit_code": -3,
                "message": "Waypoint entered error state."
            }
        elif waypoint.state == "current":
            result = {
                "exit_code": 0,
                "message": "Waypoint '%s' activated" % reference
            }
        else:
            if waypoint.wait_for("state", "current", timeout=100):
                result = {
                    "exit_code": 0,
                    "message": "Waypoint '%s' activated" % reference
                }
            else:
                waypoint.invalidate_recordset()
                if waypoint.exists() and waypoint.state == "error":
                    result = {
                        "exit_code": -3,
                        "message": "Waypoint entered error state."
                    }
                else:
                    result = {
                        "exit_code": -4,
                        "message": "Timeout waiting for activation."
                    }
